insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000001741', 'construct', '/kənˈstrʌkt/', 'verb', 'construir', 'This bridge was constructed in 1990.', 'Esta ponte foi construída em 1990.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001742', 'announce', '/əˈnaʊns/', 'verb', 'anunciar', 'The winners will be announced tomorrow.', 'Os vencedores serão anunciados amanhã.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001743', 'discover', '/dɪˈskʌvər/', 'verb', 'descobrir', 'New species can be discovered in the rainforest.', 'Novas espécies podem ser descobertas na floresta tropical.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001744', 'launch', '/lɔːntʃ/', 'verb', 'lançar', 'The new product will be launched next month.', 'O novo produto será lançado no próximo mês.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001745', 'develop', '/dɪˈveləp/', 'verb', 'desenvolver', 'A vaccine must be developed quickly.', 'Uma vacina deve ser desenvolvida rapidamente.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001746', 'install', '/ɪnˈstɔːl/', 'verb', 'instalar', 'New software should be installed on all computers.', 'Um novo software deve ser instalado em todos os computadores.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001747', 'publish', '/ˈpʌblɪʃ/', 'verb', 'publicar', 'The report has been published online.', 'O relatório foi publicado online.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001748', 'appoint', '/əˈpɔɪnt/', 'verb', 'nomear', 'She has been appointed as the new director.', 'Ela foi nomeada a nova diretora.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001749', 'elect', '/ɪˈlekt/', 'verb', 'eleger', 'He had been elected mayor before the scandal.', 'Ele tinha sido eleito prefeito antes do escândalo.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001750', 'award', '/əˈwɔːrd/', 'verb', 'premiar/conceder', 'The prize has been awarded to the best student.', 'O prêmio foi concedido ao melhor aluno.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001751', 'ban', '/bæn/', 'verb', 'proibir', 'Smoking has been banned in this building since 2015.', 'Fumar é proibido neste prédio desde 2015.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001752', 'damage', '/ˈdæmɪdʒ/', 'verb', 'danificar', 'The car had been damaged before the accident.', 'O carro já tinha sido danificado antes do acidente.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001753', 'repair', '/rɪˈper/', 'verb', 'consertar', 'The road is being repaired this week.', 'A estrada está sendo consertada esta semana.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001754', 'deliver', '/dɪˈlɪvər/', 'verb', 'entregar', 'The furniture was being delivered when it started to rain.', 'A mobília estava sendo entregue quando começou a chover.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001755', 'manufacture', '/ˌmænjuˈfæktʃər/', 'verb', 'fabricar', 'These cars are being manufactured in a new factory.', 'Esses carros estão sendo fabricados em uma nova fábrica.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001756', 'distribute', '/dɪˈstrɪbjuːt/', 'verb', 'distribuir', 'The flyers were being distributed all morning.', 'Os panfletos estavam sendo distribuídos a manhã toda.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001757', 'approve', '/əˈpruːv/', 'verb', 'aprovar', 'It is believed that the budget will be approved soon.', 'Acredita-se que o orçamento será aprovado em breve.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001758', 'reject', '/rɪˈdʒekt/', 'verb', 'rejeitar', 'It is said that his application was rejected twice.', 'Diz-se que a candidatura dele foi rejeitada duas vezes.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001759', 'suspend', '/səˈspend/', 'verb', 'suspender', 'The player is reported to have been suspended for two matches.', 'Relata-se que o jogador foi suspenso por duas partidas.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001760', 'investigate', '/ɪnˈvestɪɡeɪt/', 'verb', 'investigar', 'The crime is believed to be being investigated by the police.', 'Acredita-se que o crime está sendo investigado pela polícia.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001761', 'arrest', '/əˈrest/', 'verb', 'prender', 'It is thought that the suspect was arrested last night.', 'Pensa-se que o suspeito foi preso ontem à noite.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001762', 'charge', '/tʃɑːrdʒ/', 'verb', 'acusar', 'He is said to have been charged with theft.', 'Diz-se que ele foi acusado de roubo.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001763', 'sentence', '/ˈsentəns/', 'verb', 'sentenciar', 'It is reported that she was sentenced to five years.', 'Relata-se que ela foi sentenciada a cinco anos.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001764', 'release', '/rɪˈliːs/', 'verb', 'liberar/lançar', 'It is rumored that the movie will be released early.', 'Rumores dizem que o filme será lançado antes do previsto.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001765', 'fund', '/fʌnd/', 'verb', 'financiar', 'The project is funded by the government.', 'O projeto é financiado pelo governo.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001766', 'sponsor', '/ˈspɑːnsər/', 'verb', 'patrocinar', 'The event is sponsored by a local bank.', 'O evento é patrocinado por um banco local.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001767', 'complete', '/kəmˈpliːt/', 'verb', 'completar', 'The building will have been completed by the end of the year.', 'O prédio terá sido concluído até o final do ano.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001768', 'cancel', '/ˈkænsəl/', 'verb', 'cancelar', 'The flight might be cancelled due to bad weather.', 'O voo pode ser cancelado devido ao mau tempo.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001769', 'postpone', '/poʊstˈpoʊn/', 'verb', 'adiar', 'The meeting has been postponed until Friday.', 'A reunião foi adiada para sexta-feira.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001770', 'update', '/ʌpˈdeɪt/', 'verb', 'atualizar', 'The website is updated every day.', 'O site é atualizado todos os dias.', 'B2', array['grammar']);

