-- Lição 291: Passiva com modais (construct, announce, discover, launch, develop, install)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000291', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001741", "show_image": false}'),
('20000000-0000-0000-0000-000000000291', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001744", "show_image": false}'),
('20000000-0000-0000-0000-000000000291', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001746", "show_image": false}'),
('20000000-0000-0000-0000-000000000291', 'multiple_choice', 4, '{"question": "This bridge ___ within two years.", "audio_text": null, "options": ["should be constructed", "should construct", "should constructed"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000291', 'multiple_choice', 5, '{"question": "New species can ___ in the rainforest.", "audio_text": null, "options": ["be discovered", "discover", "be discover"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000291', 'matching', 6, '{"pairs": [{"left": "construct", "right": "construir"}, {"left": "announce", "right": "anunciar"}, {"left": "discover", "right": "descobrir"}, {"left": "launch", "right": "lançar"}, {"left": "develop", "right": "desenvolver"}, {"left": "install", "right": "instalar"}]}'),
('20000000-0000-0000-0000-000000000291', 'fill_blank', 7, '{"sentence": "A vaccine must be ___ quickly.", "options": ["developed", "develop", "developing"], "correct": "developed", "translation": "Uma vacina deve ser desenvolvida rapidamente."}'),
('20000000-0000-0000-0000-000000000291', 'fill_blank', 8, '{"sentence": "New software should be ___ on all computers.", "options": ["installed", "install", "installing"], "correct": "installed", "translation": "Um novo software deve ser instalado em todos os computadores."}'),
('20000000-0000-0000-0000-000000000291', 'word_order', 9, '{"words": ["The", "winners", "will", "be", "announced", "tomorrow"], "correct_sentence": "The winners will be announced tomorrow", "translation": "Os vencedores serão anunciados amanhã"}'),
('20000000-0000-0000-0000-000000000291', 'word_order', 10, '{"words": ["The", "new", "product", "will", "be", "launched", "next", "month"], "correct_sentence": "The new product will be launched next month", "translation": "O novo produto será lançado no próximo mês"}'),
('20000000-0000-0000-0000-000000000291', 'reading', 11, '{"passage": "In formal English, modal verbs are often combined with the passive voice. A new bridge should be constructed within two years, and the winners of the competition will be announced tomorrow. Scientists also say that new species can still be discovered in remote rainforests.", "translation": "No inglês formal, os verbos modais costumam ser combinados com a voz passiva. Uma nova ponte deve ser construída em dois anos, e os vencedores da competição serão anunciados amanhã. Cientistas também dizem que novas espécies ainda podem ser descobertas em florestas tropicais remotas.", "question": "According to the text, what will be announced tomorrow?", "options": ["A new bridge", "The winners of the competition", "A new species"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000291', 'listening', 12, '{"audio_text": "This bridge should be constructed within two years. A vaccine must be developed quickly. New software should be installed on all computers.", "question": "What must be developed quickly, according to the audio?", "options": ["A bridge", "A vaccine", "New software"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000291', 'dictation', 13, '{"audio_text": "The winners will be announced tomorrow.", "expected": "The winners will be announced tomorrow."}'),
('20000000-0000-0000-0000-000000000291', 'typing', 14, '{"prompt_pt": "Traduza: ''O novo produto deve ser lançado antes do fim do ano.''", "expected": "The new product should be launched before the end of the year.", "ai_review": true}'),

