('20000000-0000-0000-0000-000000000292', 'matching', 6, '{"pairs": [{"left": "publish", "right": "publicar"}, {"left": "appoint", "right": "nomear"}, {"left": "elect", "right": "eleger"}, {"left": "award", "right": "premiar/conceder"}, {"left": "ban", "right": "proibir"}, {"left": "damage", "right": "danificar"}]}'),
('20000000-0000-0000-0000-000000000292', 'fill_blank', 7, '{"sentence": "The prize ___ to the best student.", "options": ["has been awarded", "has awarded", "was award"], "correct": "has been awarded", "translation": "O prêmio foi concedido ao melhor aluno."}'),
('20000000-0000-0000-0000-000000000292', 'fill_blank', 8, '{"sentence": "The car ___ before the accident.", "options": ["had been damaged", "has damaged", "was damage"], "correct": "had been damaged", "translation": "O carro já tinha sido danificado antes do acidente."}'),
('20000000-0000-0000-0000-000000000292', 'word_order', 9, '{"words": ["She", "has", "been", "appointed", "as", "the", "new", "director"], "correct_sentence": "She has been appointed as the new director", "translation": "Ela foi nomeada a nova diretora"}'),
('20000000-0000-0000-0000-000000000292', 'word_order', 10, '{"words": ["Smoking", "has", "been", "banned", "in", "this", "building", "since", "2015"], "correct_sentence": "Smoking has been banned in this building since 2015", "translation": "Fumar é proibido neste prédio desde 2015"}'),
('20000000-0000-0000-0000-000000000292', 'reading', 11, '{"passage": "The perfect tenses combine naturally with the passive voice. The report has been published online, and the winner of last year''s award has been announced already. Meanwhile, in the city center, smoking has been banned since 2015, and an old building had been damaged long before it was finally repaired.", "translation": "Os tempos perfeitos combinam naturalmente com a voz passiva. O relatório foi publicado online, e o vencedor do prêmio do ano passado já foi anunciado. Enquanto isso, no centro da cidade, fumar é proibido desde 2015, e um prédio antigo já tinha sido danificado muito antes de finalmente ser reformado.", "question": "Since when has smoking been banned in the city center, according to the text?", "options": ["2010", "2015", "2020"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000292', 'listening', 12, '{"audio_text": "The report has been published online. She has been appointed as the new director. Smoking has been banned in this building since 2015.", "question": "What has been published, according to the audio?", "options": ["A book", "The report", "A letter"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000292', 'dictation', 13, '{"audio_text": "She has been appointed as the new director.", "expected": "She has been appointed as the new director."}'),
('20000000-0000-0000-0000-000000000292', 'typing', 14, '{"prompt_pt": "Traduza: ''O prêmio já tinha sido concedido antes do anúncio oficial.''", "expected": "The prize had already been awarded before the official announcement.", "ai_review": true}'),

