('20000000-0000-0000-0000-000000000293', 'multiple_choice', 4, '{"question": "The road ___ this week.", "audio_text": null, "options": ["is being repaired", "is repaired", "was repair"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000293', 'multiple_choice', 5, '{"question": "The furniture ___ when it started to rain.", "audio_text": null, "options": ["was being delivered", "was delivered", "is deliver"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000293', 'matching', 6, '{"pairs": [{"left": "repair", "right": "consertar"}, {"left": "deliver", "right": "entregar"}, {"left": "manufacture", "right": "fabricar"}, {"left": "distribute", "right": "distribuir"}, {"left": "approve", "right": "aprovar"}, {"left": "reject", "right": "rejeitar"}]}'),
('20000000-0000-0000-0000-000000000293', 'fill_blank', 7, '{"sentence": "These cars ___ in a new factory.", "options": ["are being manufactured", "are manufactured", "was manufacturing"], "correct": "are being manufactured", "translation": "Esses carros estão sendo fabricados em uma nova fábrica."}'),
('20000000-0000-0000-0000-000000000293', 'fill_blank', 8, '{"sentence": "The flyers ___ all morning.", "options": ["were being distributed", "were distributed", "was distributing"], "correct": "were being distributed", "translation": "Os panfletos estavam sendo distribuídos a manhã toda."}'),
('20000000-0000-0000-0000-000000000293', 'word_order', 9, '{"words": ["The", "road", "is", "being", "repaired", "this", "week"], "correct_sentence": "The road is being repaired this week", "translation": "A estrada está sendo consertada esta semana"}'),
('20000000-0000-0000-0000-000000000293', 'word_order', 10, '{"words": ["The", "furniture", "was", "being", "delivered", "when", "it", "started", "to", "rain"], "correct_sentence": "The furniture was being delivered when it started to rain", "translation": "A mobília estava sendo entregue quando começou a chover"}'),
('20000000-0000-0000-0000-000000000293', 'reading', 11, '{"passage": "The continuous passive describes an action in progress. Right now, the road is being repaired, and new cars are being manufactured in a modern factory nearby. Yesterday, while the flyers were being distributed downtown, a proposal was being approved in a meeting across the street.", "translation": "A passiva contínua descreve uma ação em andamento. Agora, a estrada está sendo consertada, e novos carros estão sendo fabricados em uma fábrica moderna perto dali. Ontem, enquanto os panfletos estavam sendo distribuídos no centro, uma proposta estava sendo aprovada em uma reunião do outro lado da rua.", "question": "What is happening to the road right now, according to the text?", "options": ["It is being built", "It is being repaired", "It is being closed"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000293', 'listening', 12, '{"audio_text": "The road is being repaired this week. These cars are being manufactured in a new factory. The flyers were being distributed all morning.", "question": "What is being repaired, according to the audio?", "options": ["A factory", "The road", "A car"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000293', 'dictation', 13, '{"audio_text": "The road is being repaired this week.", "expected": "The road is being repaired this week."}'),
('20000000-0000-0000-0000-000000000293', 'typing', 14, '{"prompt_pt": "Traduza: ''O pedido dele estava sendo analisado quando o prazo terminou.''", "expected": "His request was being reviewed when the deadline ended.", "ai_review": true}'),

-- Lição 294: Passiva com verbos de comunicação (suspend, investigate, arrest, charge, sentence, release)
('20000000-0000-0000-0000-000000000294', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001760", "show_image": false}'),
('20000000-0000-0000-0000-000000000294', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001762", "show_image": false}'),
('20000000-0000-0000-0000-000000000294', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001764", "show_image": false}'),
('20000000-0000-0000-0000-000000000294', 'multiple_choice', 4, '{"question": "The crime ___ to be being investigated by the police.", "audio_text": null, "options": ["is believed", "believes", "is believing"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000294', 'multiple_choice', 5, '{"question": "He ___ to have been charged with theft.", "audio_text": null, "options": ["is said", "says", "is saying"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000294', 'matching', 6, '{"pairs": [{"left": "suspend", "right": "suspender"}, {"left": "investigate", "right": "investigar"}, {"left": "arrest", "right": "prender"}, {"left": "charge", "right": "acusar"}, {"left": "sentence", "right": "sentenciar"}, {"left": "release", "right": "liberar/lançar"}]}'),
('20000000-0000-0000-0000-000000000294', 'fill_blank', 7, '{"sentence": "It is ___ that she was sentenced to five years.", "options": ["reported", "reporting", "report"], "correct": "reported", "translation": "Relata-se que ela foi sentenciada a cinco anos."}'),
('20000000-0000-0000-0000-000000000294', 'fill_blank', 8, '{"sentence": "It is ___ that the movie will be released early.", "options": ["rumored", "rumoring", "rumor"], "correct": "rumored", "translation": "Rumores dizem que o filme será lançado antes do previsto."}'),
('20000000-0000-0000-0000-000000000294', 'word_order', 9, '{"words": ["It", "is", "thought", "that", "the", "suspect", "was", "arrested", "last", "night"], "correct_sentence": "It is thought that the suspect was arrested last night", "translation": "Pensa-se que o suspeito foi preso ontem à noite"}'),
('20000000-0000-0000-0000-000000000294', 'word_order', 10, '{"words": ["The", "player", "is", "reported", "to", "have", "been", "suspended"], "correct_sentence": "The player is reported to have been suspended", "translation": "Relata-se que o jogador foi suspenso"}'),
('20000000-0000-0000-0000-000000000294', 'reading', 11, '{"passage": "News reports often use passive structures with verbs like ''said'', ''believed'' and ''reported'' to describe events without naming a clear source. It is believed that the crime is being investigated by the police, and the main suspect is said to have been arrested last night. He is reported to have been charged with theft, though it is not yet confirmed whether he will be sentenced.", "translation": "Notícias costumam usar estruturas passivas com verbos como ''said'', ''believed'' e ''reported'' para descrever eventos sem citar uma fonte clara. Acredita-se que o crime está sendo investigado pela polícia, e o principal suspeito é dito ter sido preso ontem à noite. Relata-se que ele foi acusado de roubo, embora ainda não esteja confirmado se ele será sentenciado.", "question": "According to the text, what is the suspect reported to have been charged with?", "options": ["Assault", "Theft", "Fraud"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000294', 'listening', 12, '{"audio_text": "It is believed that the crime is being investigated by the police. He is said to have been charged with theft. It is reported that she was sentenced to five years.", "question": "What is he said to have been charged with, according to the audio?", "options": ["Theft", "Fraud", "Assault"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000294', 'dictation', 13, '{"audio_text": "It is thought that the suspect was arrested last night.", "expected": "It is thought that the suspect was arrested last night."}'),
('20000000-0000-0000-0000-000000000294', 'typing', 14, '{"prompt_pt": "Traduza: ''Diz-se que ele foi liberado depois de pagar a fiança.''", "expected": "He is said to have been released after paying bail.", "ai_review": true}'),

